window.NITI_SESSION_CATALOG = {"version":1,"moduleId":"olympus2207-tartar","exposure":"GM ONLY: send each selected quest.public to players. Never send this full catalog, results, itemEvents, caveats or source fields.","rules":{"xp":"Each confirmed participant gets quest completion XP once. Alternative result paths of a quest share one completion onceKey. Total600.","items":"All item quantities describe a single group pool, not one copy for every player. GM selects recipient or shared inventory.","events":"Item events give0XP and each has its own onceKey. Selecting an item event must not mark quest complete.","consumption":"Inventory consumption must be implemented transactionally if used; never add a consumed quest delivery item as final loot.","failure":"A failed check does not automatically mean quest completion or XP. Record a result without rewards unless completion conditions actually met.","public":"Only explicitly whitelisted title/place/description/actions sent. Do not derive choices from raw check text, success/failure, goals or extras.","stages":"Initial actions are deliberately broad. GM may replace current public actions when events reveal more. Do not expose future stages/loot in advance."},"quests":[{"id":"q1","public":{"title":"Найти отцовский ключ","place":"Семейная комната","description":"Найди мой маленький газовый ключ с деревянной ручкой.","actions":[{"id":"q1-action-1","label":"Помочь отцу вспомнить, где остался ключ"},{"id":"q1-action-2","label":"Расспросить семью"},{"id":"q1-action-3","label":"Самостоятельно поискать ключ"},{"id":"q1-action-4","label":"Попробовать взять ключ незаметно"}]},"completionXP":50,"results":[{"id":"returned","label":"Ключ физически возвращён отцу","publicText":"Ключ возвращён отцу. Он благодарит вас и передаёт алюминиевый кастет.","xp":50,"items":[{"name":"Алюминиевый кастет","quantity":1,"scope":"group"}],"completion":true,"onceKey":"q1-completion","source":"Задание 1, завершение / опыт"},{"id":"remembered","label":"Отец вспомнил владельца; доставка не понадобилась","publicText":"Отец вспомнил, кому отдал ключ. Поручение завершено.","xp":50,"items":[],"completion":true,"onceKey":"q1-completion","source":"Задание 1, завершение / опыт"}],"itemEvents":[{"id":"key-found","label":"Ключ получен; ещё не возвращён","publicText":"Вы получили маленький газовый ключ с деревянной ручкой.","xp":0,"items":[{"name":"Газовый ключ отца","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q1-key-found","source":"Задание 1, предмет / этап"},{"id":"key-returned","label":"Списать возвращённый ключ из инвентаря","publicText":"Ключ передан отцу.","xp":0,"items":[],"consume":[{"name":"Газовый ключ отца","quantity":1,"scope":"group"}],"completion":false,"onceKey":"q1-key-returned","source":"Задание 1, предмет / этап"}],"caveats":["Кастет только за физический возврат, один на группу. Газовый ключ — предмет поручения: не выдавать ещё один после возврата. Альтернативные способы не дают повторного опыта."]},{"id":"q2","public":{"title":"Защитить Кирка от Булли","place":"Жилой сектор","description":"Булли снова меня задирает. Помоги сделать так, чтобы он отстал.","actions":[{"id":"q2-action-1","label":"Попробовать договориться с Булли"},{"id":"q2-action-2","label":"Пригрозить Булли"},{"id":"q2-action-3","label":"Вступиться за Кирка в драке"},{"id":"q2-action-4","label":"Попросить Кирка помочь"},{"id":"q2-action-5","label":"Обратиться за помощью к родителям"}]},"completionXP":40,"results":[{"id":"peaceful","label":"Травля прекращена; Кирку сообщили","publicText":"Кирк узнал, что травля прекращена. Вы помогли ему.","xp":40,"items":[],"completion":true,"onceKey":"q2-completion","source":"Задание 2, завершение / опыт"},{"id":"fight","label":"Булли сдался; Кирку сообщили","publicText":"Булли отступил. Кирк узнал, что вы защитили его.","xp":40,"items":[],"completion":true,"onceKey":"q2-completion","source":"Задание 2, завершение / опыт"},{"id":"adults","label":"Взрослые прекратили травлю; Кирку сообщили","publicText":"Взрослые вмешались, и травля Кирка прекращена.","xp":40,"items":[],"completion":true,"onceKey":"q2-completion","source":"Задание 2, завершение / опыт"}],"itemEvents":[],"caveats":["За проигранную драку или отказ продолжать завершения нет. Не начислять отдельно за бой и не выдавать предметы."]},{"id":"q3","public":{"title":"Достать Рад Аут для Стеллы","place":"Комната семьи Кэтти","description":"Маме нужен “Рад-Аут”. Попробуй попросить его у доктора.","actions":[{"id":"q3-action-1","label":"Попросить лекарство у Пата"},{"id":"q3-action-2","label":"Предложить оплату"},{"id":"q3-action-3","label":"Попросить выдать лекарство в долг"},{"id":"q3-action-4","label":"Привести больную с сопровождающим к доктору"},{"id":"q3-action-5","label":"Расспросить доктора о лечении"},{"id":"q3-action-6","label":"Попробовать незаметно взять лекарство"}]},"completionXP":50,"results":[{"id":"medicine-delivered","label":"Препарат передан и действительно применён для лечения","publicText":"Лекарство передано для лечения Стеллы. Поручение выполнено.","xp":50,"items":[],"completion":true,"onceKey":"q3-completion","source":"Задание 3, завершение / опыт"},{"id":"doctor-treated","label":"Пат лично вылечил Стеллу","publicText":"Пат оказал Стелле необходимую помощь.","xp":50,"items":[],"completion":true,"onceKey":"q3-completion","source":"Задание 3, завершение / опыт"}],"itemEvents":[{"id":"radout-obtained","label":"Одна доза Рад-Аута получена для Стеллы","publicText":"Вы получили одну дозу Рад-Аута для Стеллы.","xp":0,"items":[{"name":"Рад-Аут","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q3-radout-obtained","source":"Задание 3, предмет / этап"},{"id":"radout-delivered","label":"Переданная доза расходована на лечение","publicText":"Доза Рад-Аута передана для лечения Стеллы.","xp":0,"items":[],"consume":[{"name":"Рад-Аут","quantity":1,"scope":"group"}],"completion":false,"onceKey":"q3-radout-delivered","source":"Задание 3, предмет / этап"}],"caveats":["Рад-Аут — лекарство для Стеллы, а не финальная награда героям. При передаче убрать полученную дозу из инвентаря. В долг возникает долг семьи20батареек; приобретение покупкой стоит20батареек, не награда. Запасные дозы не даютXP."]},{"id":"q4","public":{"title":"Принести ядерный напиток Сыну Богов","place":"Переход на фермы","description":"Вот одиннадцать конфет. Принеси бутылку ядерного напитка.","actions":[{"id":"q4-action-1","label":"Найти пустую бутылку"},{"id":"q4-action-2","label":"Поговорить со Смитти"},{"id":"q4-action-3","label":"Осмотреть аппарат"},{"id":"q4-action-4","label":"Попробовать незаметно добраться до аппарата"},{"id":"q4-action-5","label":"Найти способ отвлечь помеху"},{"id":"q4-action-6","label":"Обсудить поручение с охранником"}]},"completionXP":30,"results":[{"id":"drink-delivered","label":"Напиток передан охраннику","publicText":"Бутылка напитка передана охраннику. Поручение выполнено.","xp":30,"items":[],"completion":true,"onceKey":"q4-completion","source":"Задание 4, завершение / опыт"},{"id":"levy-cancelled","label":"Побор отменён; оставшиеся конфеты возвращены","publicText":"Охранник согласился пропустить вас без напитка.","xp":30,"items":[],"completion":true,"onceKey":"q4-completion","source":"Задание 4, завершение / опыт"}],"itemEvents":[{"id":"candies-received","label":"Получены11конфет на поручение","publicText":"Охранник передал вам конфеты для поручения.","xp":0,"items":[{"name":"Конфета","quantity":11,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q4-candies-received","source":"Задание 4, предмет / этап"},{"id":"parking-bottle","label":"Получена бутылка из автомобиля","publicText":"Вы нашли пустую бутылку.","xp":0,"items":[{"name":"Пустая бутылка","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q4-parking-bottle","source":"Задание 4, предмет / этап"},{"id":"smitty-bottle","label":"Получена бутылка от Смитти за улучшение","publicText":"Смитти передал вам пустую бутылку.","xp":0,"items":[{"name":"Пустая бутылка","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q4-smitty-bottle","source":"Задание 4, предмет / этап"},{"id":"spare-drink","label":"После изготовления и сдачи осталась вторая бутылка","publicText":"Вторая бутылка ядерного напитка осталась у вас.","xp":0,"items":[{"name":"Ядерный напиток","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q4-spare-drink","source":"Задание 4, предмет / этап"}],"caveats":["Вторая бутылка напитка остаётся группе только если аппарат улучшен, имеются две пустые бутылки и оплачено производство. Финальное завершение само по себе запасную бутылку не даёт. При отмене побора вернуть оставшиеся конфеты; количество зависит от фактических трат. Крыса входит вXP. Бутылки/конфеты/готовый напиток требуют учёта расхода, иначе не выдавать автоматически."]},{"id":"q5","public":{"title":"Починить трансформатор","place":"Техуровень","description":"Восстанови трансформатор. Он должен работать до конца смены.","actions":[{"id":"q5-action-1","label":"Изучить схему трансформатора"},{"id":"q5-action-2","label":"Подготовить инструмент и детали"},{"id":"q5-action-3","label":"Попробовать провести ремонт"},{"id":"q5-action-4","label":"Обратиться к Кэрол"},{"id":"q5-action-5","label":"Попросить Смитти о помощи"}]},"completionXP":60,"results":[{"id":"repaired","label":"Трансформатор исправен; отметка мастера получена; доклад сдан","publicText":"Трансформатор восстановлен. Работа принята.","xp":60,"items":[],"completion":true,"onceKey":"q5-completion","source":"Задание 5, завершение / опыт"}],"itemEvents":[],"caveats":["Сам ремонт без отметки мастера и доклада Грегориусу ещё не завершает цель. Инструменты и вкладыш не являются наградой. Напиток Смитти расходуется, если выбран этот способ. Не раскрывать игрокам будущий эффект заслонки."]},{"id":"q6","public":{"title":"Выяснить причину болезни лавашей","place":"Фермы","description":"Узнай, отчего болеют лаваши. Мне нужна причина.","actions":[{"id":"q6-action-1","label":"Осмотреть поилки"},{"id":"q6-action-2","label":"Осмотреть животных"},{"id":"q6-action-3","label":"Сравнить пробы воды"},{"id":"q6-action-4","label":"Расспросить смотрителей"},{"id":"q6-action-5","label":"Проверить оборудование"}]},"completionXP":40,"results":[{"id":"diagnosed","label":"Причина установлена; доклад смотрителям / Грегориусу сдан","publicText":"Вы выяснили причину болезни и сообщили о ней. Следующий шаг — восстановить подачу чистой воды.","xp":40,"items":[],"completion":true,"onceKey":"q6-completion","source":"Задание 6, завершение / опыт"}],"itemEvents":[],"caveats":["Не отправлять игрокам диагноз до подтверждённого результата. Расследование и ремонт очистителя — разные задания с отдельнымXP. Предметной награды нет."]},{"id":"q7","public":{"title":"Починить водоочиститель","place":"Водоочиститель","description":"Нужны фильтр, кронштейн и клапан. Соберёшь — восстановим подачу.","actions":[{"id":"q7-action-1","label":"Расспросить Смитти о необходимых деталях"},{"id":"q7-action-2","label":"Найти фильтр"},{"id":"q7-action-3","label":"Найти кронштейн"},{"id":"q7-action-4","label":"Найти клапан"},{"id":"q7-action-5","label":"Обратиться к Кэрол за помощью"},{"id":"q7-action-6","label":"Попробовать собрать блок"},{"id":"q7-action-7","label":"Проверить воду после ремонта"}]},"completionXP":70,"results":[{"id":"repaired","label":"Очиститель работает; чистая проба получена; доклад сдан","publicText":"Очиститель восстановлен. Проба воды чистая, работа принята.","xp":70,"items":[],"completion":true,"onceKey":"q7-completion","source":"Задание 7, завершение / опыт"}],"itemEvents":[{"id":"filter","label":"Мембранный фильтр получен","publicText":"Получен мембранный фильтр для очистителя.","xp":0,"items":[{"name":"Мембранный фильтр","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q7-filter","source":"Задание 7, предмет / этап"},{"id":"bracket","label":"Кронштейн получен или изготовлен","publicText":"Получен кронштейн для очистителя.","xp":0,"items":[{"name":"Кронштейн","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q7-bracket","source":"Задание 7, предмет / этап"},{"id":"valve","label":"Впускной клапан получен","publicText":"Получен впускной клапан для очистителя.","xp":0,"items":[{"name":"Впускной клапан","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q7-valve","source":"Задание 7, предмет / этап"},{"id":"parts-installed","label":"Детали установлены в очиститель","publicText":"Фильтр, кронштейн и клапан установлены в очиститель.","xp":0,"items":[],"consume":[{"name":"Мембранный фильтр","quantity":1,"scope":"group"},{"name":"Кронштейн","quantity":1,"scope":"group"},{"name":"Впускной клапан","quantity":1,"scope":"group"}],"completion":false,"onceKey":"q7-parts-installed","source":"Задание 7, предмет / этап"}],"caveats":["Детали остаются в узле; не выдавать их как финальную награду. Обвинение Брука — отдельная последующая развилка безXP, не публиковать до раскрытия. Изготовление замены уКэрол заменяет кронштейн ребёнка, не добавляет второй."]},{"id":"q8","public":{"title":"Доставить двенадцать канистр воды","place":"Склад техуровня и фермы","description":"Принеси на фермы двенадцать канистр чистой воды.","actions":[{"id":"q8-action-1","label":"Перенести канистры самостоятельно"},{"id":"q8-action-2","label":"Попросить разрешение взять тележку"},{"id":"q8-action-3","label":"Поговорить со смотрителями"},{"id":"q8-action-4","label":"Изучить ведомость обязанностей"}]},"completionXP":35,"results":[{"id":"delivered","label":"Все12канистр чистой воды приняты под отметку","publicText":"Все двенадцать канистр чистой воды доставлены и приняты.","xp":35,"items":[],"completion":true,"onceKey":"q8-completion","source":"Задание 8, завершение / опыт"}],"itemEvents":[],"caveats":["Канистры и вода — груз для сдачи, не финальная награда. Грязная вода, неполная партия или просто оставленные канистры ещё не завершают цель. Не раскрывать будущую помощь работников."]},{"id":"q9","public":{"title":"Собрать двадцать четыре початка","place":"Грядки ферм","description":"Помоги сдать норму. Мне нужны двадцать четыре спелых початка.","actions":[{"id":"q9-action-1","label":"Постараться собрать норму быстро"},{"id":"q9-action-2","label":"Работать без спешки"},{"id":"q9-action-3","label":"Попросить другого работника помочь"},{"id":"q9-action-4","label":"Передать собранный урожай"}]},"completionXP":25,"results":[{"id":"catty","label":"Кэтти получила24зрелых початка","publicText":"Норма сдана. В благодарность вы получили лепёшку.","xp":25,"items":[{"name":"Лепёшка","quantity":1,"scope":"group"}],"completion":true,"onceKey":"q9-completion","source":"Задание 9, завершение / опыт"},{"id":"foreman","label":"Альтернатива через смотрителя:24початка сданы в помощь Стелле","publicText":"Норма сдана в помощь Стелле. Вы получили лепёшку.","xp":25,"items":[{"name":"Лепёшка","quantity":1,"scope":"group"}],"completion":true,"onceKey":"q9-completion","source":"Задание 9, завершение / опыт"}],"itemEvents":[],"caveats":["Одна лепёшка на группу; початки остаются хозяйству. Альтернатива через смотрителя сохраняет награду, но не восстанавливает довериеКэтти. Лепёшку нельзя автоматически приравнивать к пайку для приманки: это решение ведущего."]},{"id":"q10","public":{"title":"Бардок у западной стены","place":"Западная стена старой парковки","description":"Отойди от стены. Тебе не нужно знать, что там.","actions":[{"id":"q10-action-1","label":"Поговорить с Бардоком"},{"id":"q10-action-2","label":"Предложить поговорить за напитком"},{"id":"q10-action-3","label":"Осмотреть стену и окрестности"},{"id":"q10-action-4","label":"Попросить помощи у Смитти"},{"id":"q10-action-5","label":"Попробовать получить доступ к стене"}]},"completionXP":50,"results":[{"id":"reported","label":"Факт установлен; Бардок выдан Грегориусу","publicText":"Расследование завершено. Вы передали сведения Грегориусу.","xp":50,"items":[],"completion":true,"onceKey":"q10-completion","source":"Задание 10, завершение / опыт"},{"id":"concealed","label":"Факт установлен; находку скрыли, Бардок жив","publicText":"Расследование завершено. Вы решили сохранить находку в тайне.","xp":50,"items":[],"completion":true,"onceKey":"q10-completion","source":"Задание 10, завершение / опыт"},{"id":"bardok-killed","label":"Факт установлен; Бардок убит","publicText":"Расследование завершено. Бардок погиб.","xp":50,"items":[],"completion":true,"onceKey":"q10-completion","source":"Задание 10, завершение / опыт"}],"itemEvents":[{"id":"service-badge","label":"При обыске получен служебный знак","publicText":"Вы нашли служебный знак охранника.","xp":0,"items":[{"name":"Служебный знак охранника","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q10-service-badge","source":"Задание 10, предмет / этап"},{"id":"ammo-preserved","label":"Дополнительный осмотр:сохранились3пригодныхпатрона","publicText":"Вы нашли три пригодных патрона к карабину.","xp":0,"items":[{"name":"Патрон к карабину","quantity":3,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q10-ammo-preserved","source":"Задание 10, предмет / этап"}],"caveats":["Не отправлять игрокам название «тело за кладкой», скрытую цель, содержимое кладки и будущую помощь Бардока до событий. Служебный знак доступен при обыске независимо отУдачи. Пригодных патронов ровно3только при успешной дополнительной проверке; карабин как предмет добычи источник явно не выдаёт."]},{"id":"q11","public":{"title":"Принести Хилл Ап раненому охраннику","place":"Западный пост","description":"Твари меня достали. Принеси у Пата “Хилл-Ап”, быстро.","actions":[{"id":"q11-action-1","label":"Попросить у Пата лекарство для раненого"},{"id":"q11-action-2","label":"Предложить свой стимулятор"},{"id":"q11-action-3","label":"Попробовать перевязать раненого"},{"id":"q11-action-4","label":"Привести Пата к пострадавшему"},{"id":"q11-action-5","label":"Осмотреть раны"}]},"completionXP":20,"results":[{"id":"medicine-applied","label":"Лекарство применено; раненый стабилизирован","publicText":"Раненому оказана помощь, его состояние стабилизировано.","xp":20,"items":[],"completion":true,"onceKey":"q11-completion","source":"Задание 11, завершение / опыт"},{"id":"equivalent-help","label":"Равноценная помощь:успешнаяперевязкаилиличнаяпомощьПата","publicText":"Раненый получил необходимую помощь.","xp":20,"items":[],"completion":true,"onceKey":"q11-completion","source":"Задание 11, завершение / опыт"}],"itemEvents":[{"id":"hillup","label":"Пат выдал одну дозу для раненого","publicText":"Пат передал вам одну дозу Хилл-Апа для раненого.","xp":0,"items":[{"name":"Хилл-Ап","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q11-hillup","source":"Задание 11, предмет / этап"},{"id":"hillup-applied","label":"Полученная доза применена к раненому","publicText":"Доза Хилл-Апа применена к раненому.","xp":0,"items":[],"consume":[{"name":"Хилл-Ап","quantity":1,"scope":"group"}],"completion":false,"onceKey":"q11-hillup-applied","source":"Задание 11, предмет / этап"}],"caveats":["Хилл-Ап получают для раненого и расходуют при применении; это не финальная награда. Осмотр ран сам по себе не даётXP. Не раскрывать будущую подставу/порогпереговоров."]},{"id":"q12","public":{"title":"Пережить обвинение","place":"Западный пост","description":"У западного поста охранник требует: «Бросай всё и стой на месте». Героям предъявляют обвинение.","actions":[{"id":"q12-action-1","label":"Попробовать объясниться"},{"id":"q12-action-2","label":"Осмотреть обстановку"},{"id":"q12-action-3","label":"Попробовать уйти"},{"id":"q12-action-4","label":"Защититься от преследователя"},{"id":"q12-action-5","label":"Сдаться и потребовать разбирательства"}]},"completionXP":30,"results":[{"id":"exit-opportunity","label":"Обвинение пройдено; получена возможность продолжить выход","publicText":"Вы получили возможность продолжить путь наружу.","xp":30,"items":[],"completion":true,"onceKey":"q12-completion","source":"Задание 12, завершение / опыт"}],"itemEvents":[],"caveats":["Само выслушивание обвинения и одинраундзадержкиохранниканедаютXP. Задержание — альтернативная ветка, не автоматическийвыход. В публичный текст можно подставить подтверждённое обвинение в открытии прохода при guard-survived=yes; убийство при guard-survived=no; unknown оставляет нейтральнуюформулировку."]},{"id":"q13","public":{"title":"Уйти через Чистилище","place":"Чистилище","description":"Вы уходите от западного поста в сторону Чистилища.","actions":[{"id":"q13-action-1","label":"Попробовать оторваться от погони"},{"id":"q13-action-2","label":"Закрыть проход за собой"},{"id":"q13-action-3","label":"Обратиться к знакомым за помощью"},{"id":"q13-action-4","label":"Осмотреть дальнейший путь"},{"id":"q13-action-5","label":"Попробовать пройти незаметно"},{"id":"q13-action-6","label":"Защититься при столкновении"}]},"completionXP":80,"results":[{"id":"escaped","label":"Все уходящие выбрались и оторвались от преследования","publicText":"Вы выбрались наружу и оторвались от преследования.","xp":80,"items":[],"completion":true,"onceKey":"q13-completion","source":"Задание 13, завершение / опыт"}],"itemEvents":[],"caveats":["Не раскрывать заранее скрытую дверь, число врагов, условияподкрепленияилиавтоматическийпоиск. Опыт только после выхода всех уходящих и прекращенияпогони. Предметнойнаградыисточникнедает. Еслиотвлекаютпищей, одинпаёкраcходуется."]},{"id":"q14","public":{"title":"Ответвление в Чистилище","place":"Ответвление перед лестницей","description":"На пути к лестнице можно заметить отдельную сервисную комнату.","actions":[{"id":"q14-action-1","label":"Осмотреть ответвление"},{"id":"q14-action-2","label":"Попробовать открыть дверь"},{"id":"q14-action-3","label":"Осмотреть доступную комнату"},{"id":"q14-action-4","label":"Продолжить путь к выходу"}]},"completionXP":20,"results":[{"id":"disk-read","label":"Диск сохранён и прочитан","publicText":"Диск сохранён и прочитан. Вы узнали историю новобранца.","xp":20,"items":[],"completion":true,"onceKey":"q14-completion","source":"Задание 14, завершение / опыт"}],"itemEvents":[{"id":"disk-taken","label":"Диск забран","publicText":"Вы сохранили найденный диск.","xp":0,"items":[{"name":"Диск с дневником новобранца","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q14-disk-taken","source":"Задание 14, предмет / этап"},{"id":"box-1","label":"Ящик1 открыт:2бинта,1паёк","publicText":"В ящике найдены бинты и паёк.","xp":0,"items":[{"name":"Бинт","quantity":2,"scope":"group"},{"name":"Паёк","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q14-box-1","source":"Задание 14, предмет / этап"},{"id":"box-2","label":"Ящик2 открыт:целебныйпорошок,проволока","publicText":"В ящике найдены целебный порошок и проволока.","xp":0,"items":[{"name":"Целебный порошок","quantity":1,"scope":"group"},{"name":"Проволока","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q14-box-2","source":"Задание 14, предмет / этап"},{"id":"box-3","label":"Ящик3 открыт:4деталиоружия,пустоймагазин","publicText":"В ящике найдены детали оружия и пустой магазин.","xp":0,"items":[{"name":"Деталь оружия","quantity":4,"scope":"group"},{"name":"Пустой магазин","quantity":1,"scope":"group"}],"consume":[],"completion":false,"onceKey":"q14-box-3","source":"Задание 14, предмет / этап"}],"caveats":["Опыт только после прочтения; за найденный, но непрочитанный диск пока0XP. Текст дневника в источнике отсутствует: не придумывать содержание, именаДжок/Келлираскрываютсятолькопослечтения. Каждыйящикединождынагруппу,отдельноотзавершениямиссии. Лутнеприписыватьавтоматическикпрочтениюдиска."]}]};
